// Input for a run through the test webhook (npm run invoke). An empty body uses this sample.
const body = $input.first().json.body;
if (body && typeof body === "object" && Object.keys(body).length) return [{ json: body }];
return [{ json: {
  "kind": "request",
  "text": "make a video about graffiti in Mount Pleasant",
  "user": "U0TEST",
  "ts": "",
  "channel": "C0CHNAKERA9",
  "at": "2026-11-14T20:00:00.000Z"
} }];

// "Menu": what each of the client's data sources holds, from Collect, for Claude to match the
// request against. Categories are listed most common first.
const req = $("Input").first().json;
const collected = $("1 Collect").all().map((i) => i.json).filter((c) => c.ok);
const total = (t) => t.weekly.reduce((s, w) => s + w.count, 0);
const menu = collected.map((c) => ({
  source_id: c.source_id,
  label: c.dataset,
  unit: c.unit,
  categories: [...c.types].sort((a, b) => total(b) - total(a)).map((t) => t.type),
  areas: [...new Set(c.types.flatMap((t) => t.by_area.map((a) => a.area)))].sort(),
}));
// Time series (such as the unemployment rate) are listed too; Plan fetches them on demand.
for (const s of $("Client").first().json.series_sources || []) {
  menu.push({ source_id: s.id, label: s.label, unit: s.unit, kind: "series", categories: [s.topic], areas: [] });
}
if (!menu.length) return [{ json: { ok: false, menu, reason: "None of the data sources answered." } }];
return [{ json: {
  ok: true,
  menu,
  claude_body: {
    model: "claude-haiku-5-5",
    max_tokens: 2000,
    output_config: { effort: "low" },
    system: "You read what people ask NewsReels for in Slack and match it to the client's data. You get the request and a menu: for each data source, its id, label, unit, the categories in it (most common first) and the neighbourhoods it covers.\n\nDecide:\n- kind: \"video\" if they ask for a video, story, reel or clip; \"answer\" if they ask a question or for numbers; \"unclear\" if it is neither, or nothing on the menu fits.\n- source_id: the source whose categories best fit what they ask about.\n- categories: a list of categories copied exactly from that source's list: every one that fits what they ask about (for example \"graffiti\" fits each graffiti category, \"rats\" a rodent one). An empty list if they ask about the whole source.\n- topic: two or three plain words for what they asked about, such as \"graffiti\" or \"noise complaints\".\n- months: only for a source whose kind is \"series\": how many months they ask about (12 for a year, 24 for two years, 60 for five years). Default 24.\n- area: one neighbourhood copied exactly from that source's list, or null if they name none.\n- reply: only when kind is \"unclear\": one short sentence saying what you can do, with two examples drawn from the menu.\n\nReturn only a JSON object, no other text: {\"kind\": \"...\", \"source_id\": \"...\", \"categories\": [\"...\"], \"topic\": \"...\", \"area\": \"...\" or null, \"months\": 24 or null, \"reply\": \"...\" or null}\n",
    messages: [{ role: "user", content: JSON.stringify({ request: req.text, sources: menu }) }],
  },
} }];

// "Plan": reads Claude's match and checks it against the menu, so only real categories and
// neighbourhoods go on. Anything it cannot use becomes a short reply asking again.
const req = $("Input").first().json;
const { menu } = $("Menu").first().json;
const client = $("Client").first().json;
const res = $input.first().json;
const raw = String(res.content?.find((c) => c.type === "text")?.text ?? "");
let a = {};
try {
  a = JSON.parse(raw.replace(/^[\s\S]*?(\{[\s\S]*\})[\s\S]*$/, "$1"));
} catch {}
// "Who asked" looks up the name; without Slack's users:read permission it stays the user ID.
let profile = null;
try {
  profile = $("Who asked").first()?.json?.user;
} catch {}
const user_name = profile?.profile?.display_name || profile?.real_name || profile?.name || null;
const request = { ...req, user_name, parse: { model: res.model ?? null, usage: res.usage ?? null }, matched: a };
const src = menu.find((m) => m.source_id === a.source_id);
const example = `Try "@NewsReels make a video about graffiti in Mount Pleasant" or "@NewsReels how many noise complaints this week?"`;
if (a.kind === "unclear" || !src) {
  return [{ json: { ok: false, kind: "unclear", request, reply: a.reply || `I could not match that to the data. ${example}` } }];
}
const kindOf = a.kind === "answer" ? "answer" : "video";
// A time series (such as the unemployment rate) is fetched from Statistics Canada, not collected.
if (src.kind === "series") {
  const series = (client.series_sources || []).find((s) => s.id === src.source_id);
  const months = Math.min(Math.max(Math.round(Number(a.months) || 24), 6), 120);
  return [{ json: { ok: true, kind: kindOf, request: { ...request, kind: kindOf }, source_id: src.source_id, series, months, categories: [], topic: series.topic, area: null, filtered: null } }];
}
const categories = [].concat(a.categories ?? a.category ?? []).filter(Boolean);
if (categories.some((c) => !src.categories.includes(c))) {
  return [{ json: { ok: false, kind: "unclear", request, reply: `I could not find that in ${src.label}. ${example}` } }];
}
const source = client.data_sources.find((s) => s.id === src.source_id);
const area = a.area && src.areas.includes(a.area) && source.area_field ? a.area : null;
// A neighbourhood needs its own 9 weeks of data, so Collect runs again with a filter.
const filtered = area && source.area_field
  ? { ...source, filter: [source.filter, `${source.area_field} = "${area.replace(/"/g, '\\"')}"`].filter(Boolean).join(" and ") }
  : null;
const kind = a.kind === "answer" ? "answer" : "video";
const topic = String(a.topic || "").trim();
return [{ json: { ok: true, kind, request: { ...request, kind }, source_id: src.source_id, categories, topic: topic ? topic.charAt(0).toUpperCase() + topic.slice(1) : null, area, filtered } }];

// "Series story": a time series someone asked for in Slack (such as Vancouver's unemployment rate),
// as a run for Context and Write, plus a one-line answer built from the numbers. Every value on
// the chart and in the story is a value Statistics Canada published.
const plan = $("Plan").first().json;
const { data_sources, ...client } = $("Client").first().json;
const s = plan.series;
const raw = $input.first().json;
const pts = (Array.isArray(raw) ? raw[0] : raw?.[0] ?? raw)?.object?.vectorDataPoint
  || (Array.isArray(raw?.body) ? raw.body[0]?.object?.vectorDataPoint : null)
  || [];
const values = pts.filter((p) => p.value !== null && p.value !== undefined).map((p) => ({ month: String(p.refPer).slice(0, 7), value: Number(p.value) }));
if (values.length < 2) {
  return [{ json: { ok: false, kind: "unclear", request: plan.request, reply: `I could not get ${s.label} from Statistics Canada just now. Try again in a minute.` } }];
}
const name = (m) => new Date(m + "-15T12:00:00Z").toLocaleDateString("en-CA", { month: "long", year: "numeric", timeZone: "UTC" });
const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const short = (m) => `${MON[Number(m.slice(5, 7)) - 1]} \u2019${m.slice(2, 4)}`;
const first = values[0], last = values[values.length - 1];
const high = values.reduce((a, b) => (b.value > a.value ? b : a));
const low = values.reduce((a, b) => (b.value < a.value ? b : a));
const yearAgo = values.length > 12 ? values[values.length - 13] : first;
const change = Math.round((last.value - first.value) * 10) / 10;
// At most 9 points on the chart, evenly spaced, always ending on the latest month.
const step = Math.max(1, Math.ceil((values.length - 1) / 8));
const points = [];
for (let i = values.length - 1; i >= 0 && points.length < 9; i -= step) points.unshift(values[i]);
const period = values.length % 12 === 0 ? `the last ${values.length / 12} year${values.length === 12 ? "" : "s"}` : `the last ${values.length} months`;
const story = {
  kind: "series",
  dataset: s.label,
  source_note: s.source_note,
  source_url: s.source_url,
  unit: s.unit,
  type: s.topic,
  topic: s.topic,
  period,
  months: values.length,
  first_month: name(first.month),
  first_value: first.value,
  latest_month: name(last.month),
  latest_value: last.value,
  year_ago_month: name(yearAgo.month),
  year_ago_value: yearAgo.value,
  high_month: name(high.month),
  high_value: high.value,
  low_month: name(low.month),
  low_value: low.value,
  change_points: change,
  direction: change > 0.2 ? "up" : change < -0.2 ? "down" : "flat",
  chart_kind: "series",
  points: points.map((p) => ({ label: short(p.month), value: p.value })),
  values,
};
const answer = [
  `*${s.label}*: ${last.value}${s.unit} in ${story.latest_month}, against ${first.value}${s.unit} in ${story.first_month} (${period}).`,
  `Highest: ${high.value}${s.unit} in ${story.high_month}. Lowest: ${low.value}${s.unit} in ${story.low_month}. A year earlier: ${yearAgo.value}${s.unit}.`,
  `Source: <${s.source_url}|${s.source_note}>`,
].join("\n");
return [{ json: {
  ok: true,
  kind: plan.kind,
  run_id: `request-${plan.request.ts}`,
  trigger: "Slack request",
  started_at: plan.request.at,
  request: plan.request,
  client,
  story,
  runners_up: [],
  sources_checked: s.label,
  sources_failed: [],
  answer,
  answer_line: answer.split("\n")[0].replace(/\*/g, ""),
} }];

// "Requested story": the story for exactly what was asked, in the same shape Score hands to Write,
// plus a one-line answer built from the numbers (no model writes it). No bar to pass: a request
// gets its data whatever the size.
const plan = $("Plan").first().json;
const { data_sources, ...client } = $("Client").first().json;
const c = plan.filtered ? $input.first().json : $("1 Collect").all().map((i) => i.json).find((x) => x.ok && x.source_id === plan.source_id);
if (!c || !c.ok) return [{ json: { ok: false, kind: "unclear", request: plan.request, reply: `I could not get that data just now: ${c?.reason || "no answer from the city"}.` } }];

const round1 = (x) => Math.round(x * 10) / 10;
const topicOf = (t) => t.replace(/\s*-\s*311$/i, "").replace(/\s+(Request\s+)?Case$/i, "").trim();
const types = plan.categories.length ? c.types.filter((t) => plan.categories.includes(t.type)) : c.types;
const weekly = c.weeks.map((we, k) => ({ week_ending: we, count: types.reduce((s, t) => s + (t.weekly[k]?.count || 0), 0) }));
const areas = new Map();
let unknown = 0;
for (const t of types) {
  for (const a of t.by_area) areas.set(a.area, (areas.get(a.area) || 0) + a.count);
  unknown += t.unknown_area || 0;
}
const by_area = plan.area ? [] : [...areas].map(([area, count]) => ({ area, count })).sort((a, b) => b.count - a.count).slice(0, 10);
const counts = weekly.map((w) => w.count);
const thisWeek = counts[8];
const avg = round1(counts.slice(0, 8).reduce((a, b) => a + b, 0) / 8);
const ratio = avg ? round1(thisWeek / avg) : null;
const pct = avg ? Math.round(((thisWeek - avg) / avg) * 100) : null;
const direction = !avg ? (thisWeek ? "up" : "flat") : ratio >= 1.2 ? "up" : ratio <= 0.8 ? "down" : "flat";
const topic = plan.topic || (plan.categories.length === 1 ? topicOf(plan.categories[0]) : c.dataset);
const story = {
  week_start: c.week_start,
  week_ending: c.week_ending,
  dataset: c.dataset,
  source_note: c.source_note,
  source_url: c.source_url,
  unit: c.unit,
  type: plan.categories.length ? plan.categories.join("; ") : `all ${c.dataset}`,
  topic,
  area: plan.area,
  direction,
  this_week: thisWeek,
  avg_prev_8_weeks: avg,
  ratio,
  pct_change: pct,
  chart_kind: by_area.length >= 3 ? "by_area" : "weekly",
  by_area,
  unknown_area: unknown,
  weekly,
};
const change = !avg ? "none in the 8 weeks before" : direction === "up" ? `${ratio}× the usual level` : direction === "down" ? `down ${Math.abs(pct)}% from the usual level` : "about the usual level";
const answer = [
  `*${topic}${plan.area ? ` in ${plan.area}` : ""}*: ${thisWeek} ${c.unit} in the week ${c.week_start} to ${c.week_ending}, against an average of ${avg} a week over the 8 weeks before (${change}).`,
  by_area.length ? `Most this week: ${by_area.slice(0, 3).map((a) => `${a.area} ${a.count}`).join(", ")}.` : "",
  `Source: <${c.source_url}|${c.source_note}>`,
].filter(Boolean).join("\n");
return [{ json: {
  ok: true,
  kind: plan.kind,
  run_id: `request-${plan.request.ts}`,
  trigger: "Slack request",
  started_at: plan.request.at,
  request: plan.request,
  client,
  story,
  runners_up: [],
  sources_checked: c.dataset,
  sources_failed: [],
  answer,
  answer_line: answer.split("\n")[0].replace(/\*/g, ""),
} }];

// "Add trace link": keeps the run and adds the links to its trace pages, if the render service saved
// them. A failed save leaves the links empty; the run goes on.
const run = $("Numbers check out?").first().json;
const r = $input.first().json;
return [{ json: { ...run, trace_id: r.trace_id ?? null, trace_url: r.trace_url ?? null, story_page_url: r.story_url ?? null, ledger_url: r.ledger_url ?? null } }];
